    "ai_mode_assess": "Gajeren tantancewa",
    "ai_mode_support": "Taimakon koyo",
    "ai_mode_parent_note": "Daftarin saƙon iyali",
    "ai_mode_lesson_plan_prompt": "Rubuta gajeren tsarin darasin kimiyya na aji 4 game da tushe da amfanin ruwa ta tsarin 5E. Yi amfani da kalmomin Turanci 140 a mafi yawa.",
    "ai_mode_explain_prompt": "Bayyana zagayowar ruwa cikin sauƙin Turanci ga malamin aji 4, tare da misali ɗaya na gida. Yi amfani da kalmomi 100 a mafi yawa.",
    "ai_mode_adapt_prompt": "Ba da hanyoyi uku na daidaita darasin ruwa na aji 4 ga ɗalibai masu matakan karatu daban-daban, da kayan aji marasa tsada. Yi amfani da kalmomin Turanci 120 a mafi yawa.",
    "ai_mode_assess_prompt": "Ba da tambayoyi biyar na gajeren gwajin fahimta bayan darasin tushe da amfanin ruwa na aji 4. Haɗa amsoshi. Yi amfani da kalmomin Turanci 140 a mafi yawa.",
    "ai_mode_support_prompt": "Ba da hanyoyi biyu masu amfani da malami zai iya taimaka wa ɗalibin da bai tabbata game da tushen ruwa ba, ba tare da yi masa lakabi ko gano cuta ba. Yi amfani da kalmomin Turanci 100 a mafi yawa.",
    "ai_mode_parent_note_prompt": "Rubuta gajeren saƙon iyali na gaskiya kuma na abokantaka game da darasin ruwa na mako da aikin gida ɗaya. Kada ka ambaci sunan ɗalibi, lambar waya, aji ko ganewar cuta. Yi amfani da kalmomin Turanci 60 a mafi yawa.",
    "ai_prompt_used": "Tambaya ba tare da bayanan ɗalibi ba",
    "ai_context_title": "Aji 4 · Kimiyya ta asali",
